r":"lpp.listening_stories.t2.2-31.choice3","passage":"For the performance, the choir wore green scarves over white shirts. Each singer held a small lamp. They stood in two rows on the stage. The lamps ran on batteries, so there were no open flames. The back row stood on a low step behind the front. All the scarves were the same bright shade of green. Their white shirts made those scarves easy to see from far away. These clothes and the soft lights were part of the plan.","displayPassageDuringResponse":false,"hideWrittenLabels":false,"suppressStimulusAudio":false,"allowsChoiceAudio":true,"media":{"requiredSources":[{"kind":"audio","role":"passage","path":"/audio/production/en-US/assessment_passage/for-the-performance-the-choir-wore-green-scarves-over-white-shirts-each-si-4fc5723c5f.mp3","text":"For the performance, the choir wore green scarves over white shirts. Each singer held a small lamp. They stood in two rows on the stage. The lamps ran on batteries, so there were no open flames. The back row stood on a low step behind the front. All the scarves were the same bright shade of green. Their white shirts made those scarves easy to see from far away. These clothes and the soft lights were part of the plan."}],"decision":{"itemId":"lpp.listening_stories.t2.2-31","role":"text-only","paths":[],"constructReview":"approved","answerNeutral":"not-applicable-no-pictures","rationale":"A new literal-detail question, with an explicit key in the exact recorded source passage. Public passage familiarity is unknown; known source-family exposure excludes it."}},"audio":{"instruction":{"text":"How many rows did the choir stand in?","path":"","required":false,"fallback":"speech_access"},"passage":{"text":"For the performance, the choir wore green scarves over white shirts. Each singer held a small lamp. They stood in two rows on the stage. The lamps ran on batteries, so there were no open flames. The back row stood on a low step behind the front. All the scarves were the same bright shade of green. Their white shirts made those scarves easy to see from far away. These clothes and the soft lights were part of the plan.","path":"/audio/production/en-US/assessment_passage/for-the-performance-the-choir-wore-green-scarves-over-white-shirts-each-si-4fc5723c5f.mp3","required":true,"provenance":"existing_approved_leda_passage_recording"},"choices":[{"choiceId":"lpp.listening_stories.t2.2-31.choice1","text":"one row","path":"","required":false,"fallback":"speech_access"},{"choiceId":"lpp.listening_stories.t2.2-31.choice2","text":"four rows","path":"","required":false,"fallback":"speech_access"},{"choiceId":"lpp.listening_stories.t2.2-31.choice3","text":"two rows","path":"","required":false,"fallback":"speech_access"}]},"exposure":{"itemStatus":"reserved_original_question","priorExposureStatus":"unknown","sourceReuse":"approved_public_recorded_passage","sourceItemId":"lp3.key_details.l2.A.which_is_not.v21","publicStimulusFamilyId":"passage:59e691fce55805851d5a","limitation":"The question is original; its recorded passage was previously public. Prior passage familiarity is unknown unless learner exposure records establish it."},"editorial":{"note":"A new literal-detail question, with an explicit key in the exact recorded source passage. Public passage familiarity is unknown; known source-family exposure excludes it.","keyReview":"one-explicit-key","originality":"original_question_reused_disclosed_stimulus"},"retentionOnly":false,"nonGating":false},{"id":"lpp.listening_stories.t2.2-32","instrument":"adaptive_progress","reservedPurpose":"progress_test","contentStandardVersion":3,"trackId":"listening_stories","reportStrandId":"listening_stories","construct":"heard_literal_detail_retrieval","modality":"audio","difficultyTier":2,"difficultyVersion":"progress-ordinal-2026-10-02.1","difficultyRationale":"Select a precise explicit detail in a longer passage with competing stated details.","stimulusFamilyId":"progress:listening_stories:06b2c206560d4621c793","enem