ay is forbidden."}},"audio":{"instruction":{"text":"What thread mended the real pocket?","path":"","required":false,"fallback":"speech_access"},"choices":[{"choiceId":"lpp.reading_stories.t2.2-9.choice1","text":"blue thread","path":"","required":false,"fallback":"speech_access"},{"choiceId":"lpp.reading_stories.t2.2-9.choice2","text":"white thread","path":"","required":false,"fallback":"speech_access"},{"choiceId":"lpp.reading_stories.t2.2-9.choice3","text":"red thread","path":"","required":false,"fallback":"speech_access"}]},"exposure":{"itemStatus":"reserved_original_question","priorExposureStatus":"unknown","sourceReuse":"none","limitation":"New reserved text; learner exposure must still be checked at family level."},"editorial":{"note":"The stated detail answers \"What thread mended the real pocket?\". The alternatives contradict that detail or name another stated object. Passage replay is forbidden.","keyReview":"one-explicit-key","originality":"original_reserved_content"},"retentionOnly":false,"nonGating":false},{"id":"lpp.reading_stories.t2.2-10","instrument":"adaptive_progress","reservedPurpose":"progress_test","contentStandardVersion":3,"trackId":"reading_stories","reportStrandId":"reading_stories","construct":"printed_literal_detail_retrieval","modality":"print","difficultyTier":2,"difficultyVersion":"progress-ordinal-2026-10-02.1","difficultyRationale":"Retrieve a precise explicit detail across several printed sentences with competing details.","stimulusFamilyId":"progress:reading_stories:f3d6f741ff83fe7c29d2","enemyItemGroups":["progress:reading_stories:f3d6f741ff83fe7c29d2"],"formatType":"PROGRESS_READING_DETAIL","prompt":"Which seeds did we buy?","choices":[{"id":"lpp.reading_stories.t2.2-10.choice1","label":"bean seeds","rationale":"D-OPPOSITE","audio":{"text":"bean seeds","path":"","required":false,"fallback":"speech_access"}},{"id":"lpp.reading_stories.t2.2-10.choice2","label":"flower seeds","rationale":"D-OPPOSITE","audio":{"text":"flower seeds","p