alter table public.assessment_attempts alter column accuracy drop not null;
alter table public.assessment_attempts add constraint assessment_accuracy_instrument_check
  check ((assessment_type = 'adaptive_progress_test' and accuracy is null)
    or (assessment_type <> 'adaptive_progress_test' and accuracy is not null));
alter table public.student_focus_sessions drop constraint student_focus_sessions_target_check;
alter table public.student_focus_sessions add constraint student_focus_sessions_target_check
  check (target in ('reading_library','letters_practice','skills_assessment',
    'assigned_book','arcade_game','adventure_map','cycle_practice','progress_check'));

create function public.lp_progress_config_valid(p_config jsonb, p_version text)
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_typeof(p_config) = 'object'
    and not exists(select 1 from jsonb_object_keys(p_config) k where k not in ('plan_kind','track_id','bank_version'))
    and p_config->>'bank_version' = p_version
    and exists(select 1 from public.progress_test_banks where version=p_version)
    and (p_config->>'plan_kind'='broad_profile' and coalesce(p_config->>'track_id','')=''
      or p_config->>'plan_kind'='focused' and p_config->>'track_id' in
        ('hear_sounds','printed_words','common_words','word_meaning','listening_stories','reading_stories')),false);
$$;

create function public.lp_progress_item_valid(p_snapshot jsonb, p_expected jsonb)
returns boolean language sql immutable set search_path = '' as $$
  select coalesce((p_snapshot - 'choices') #- '{audio,choices}' = (p_expected - 'choices') #- '{audio,choices}'
    and jsonb_typeof(p_snapshot->'choices')='array'
    and (select jsonb_agg(x order by x->>'id') from jsonb_array_elements(p_snapshot->'choices') x)
      = (select jsonb_agg(x order by x->>'id') from jsonb_array_elements(p_expected->'choices') x)
    and coalesce((select jsonb_agg(x order by x->>'choiceId') from jsonb_array_elements(p_snapshot#>'{audio,choices}') x),'[]'::jsonb)
      = coalesce((select jsonb_agg(x order by x->>'choiceId') from jsonb_array_elements(p_expected#>'{audio,choices}') x),'[]'::jsonb),false);
$$;

create function public.lp_validate_progress_run(p_run jsonb, p_previous jsonb default null)
returns void language plpgsql stable security definer set search_path = '' as $$
declare
  v_bank jsonb; v_item jsonb; v_expected jsonb; v_row jsonb; v_key text; v_track text;
  v_tiers jsonb := '{}'::jsonb; v_initial integer; v_before integer; v_after integer;
  v_ordinal integer := 0; v_scored integer := 0; v_correct boolean; v_status text;
  v_max integer; v_min integer; v_track_ids jsonb; v_role text; v_cue jsonb; v_audio jsonb; v_index integer;
begin
  if jsonb_typeof(p_run) is distinct from 'object' or octet_length(p_run::text)>4900000
    or p_run->>'schemaVersion' is distinct from '1'
    or char_length(coalesce(p_run->>'attemptId','')) not between 1 and 120
    or p_run->>'policyVersion' is distinct from 'progress-ordinal-v1'
    or coalesce(p_run->>'status','') not in ('warmup','running','completed','partial')
    or jsonb_typeof(p_run->'pool') is distinct from 'array'
    or jsonb_typeof(p_run->'responses') is distinct from 'array'
    or jsonb_typeof(p_run->'tracks') is distinct from 'object'
    or jsonb_typeof(p_run->'startingPoints') is distinct from 'object'
    or jsonb_typeof(p_run->'routeDecisions') is distinct from 'array'
    or jsonb_typeof(p_run->'warmupRecords') is distinct from 'array'
    or jsonb_typeof(p_run->'pauseEvents') is distinct from 'array'
  then raise exception 'Invalid progress run'; end if;
  select manifest into v_bank from public.progress_test_banks
    where version=p_run->>'contentVersion' and difficulty_version=p_run->>'difficultyVersion';
  if v_bank is null then raise exception 'Progress bank version unavailable'; end if;
  if p_run#>>'{plan,id}'='broad_profile' then
    v_min:=4; v_max:=8;
    v_track_ids:='["hear_sounds","printed_words","common_words","word_meaning","listening_stories","reading_stories"]'::jsonb;
    if p_run#>>'{plan,maximumValid}' is distinct from '36' or p_run#>>'{plan,maximumPresentations}' is distinct from '48'
      then raise exception 'Invalid progress plan'; end if;
  elsif p_run#>>'{plan,id}'='focused' then
    v_min:=10; v_max:=16; v_track_ids:=p_run#>'{plan,trackIds}';
    if jsonb_array_length(v_track_ids)<>1 or coalesce(v_track_ids->>0,'') not in
      ('hear_sounds','printed_words','common_words','word_meaning','listening_stories','reading_stories')
      or p_run#>>'{plan,maximumValid}' is distinct from '16' or p_run#>>'{plan,maximumPresentations}' is distinct from '24'
      then raise exception 'Invalid progress plan'; end if;
  else raise exception 'Invalid progress plan'; end if;
  if p_run#>'{plan,trackIds}' is distinct from v_track_ids
    or p_run#>>'{plan,minimumPerTrack}' is distinct from v_min::text
    or p_run#>>'{plan,maximumPerTrack}' is distinct from v_max::text
    or jsonb_array_length(p_run->'responses')>(p_run#>>'{plan,maximumPresentations}')::integer
    or (select count(*) from jsonb_object_keys(p_run->'tracks'))<>jsonb_array_length(v_track_ids)
    or p_run->'policySnapshot' is distinct from jsonb_build_object('version','progress-ordinal-v1','plan',p_run->'plan','firstResponseOnly',true,'recencyDays',90,'contradictionStops',false)
    or p_run#>>'{exposureSnapshot,familiarityUnknown}' is distinct from 'true'
    or jsonb_array_length(p_run->'pool')=0
  then raise exception 'Invalid progress plan'; end if;
  for v_item in select value from jsonb_array_elements(p_run->'pool') loop
    select value into v_expected from jsonb_array_elements(v_bank->'items') where value->>'id'=v_item->>'id';
    if v_expected is null or v_item<>v_expected or not v_track_ids ? (v_item->>'trackId')
      then raise exception 'Progress pool differs from the authoritative bank'; end if;
  end loop;
  if (select count(distinct x->>'id') from jsonb_array_elements(p_run->'pool') x)<>jsonb_array_length(p_run->'pool')
    then raise exception 'Duplicate progress pool item'; end if;
  for v_track in select jsonb_array_elements_text(v_track_ids) loop
    v_initial:=(p_run#>>array['startingPoints',v_track,'tier'])::integer;
    if v_initial is null or v_initial not between 0 and 2 or p_run#>>array['tracks',v_track,'minimumTier'] is distinct from '0'
      or p_run#>>array['tracks',v_track,'maximumTier'] is distinct from '2'
      then raise exception 'Invalid progress starting point'; end if;
    if (select count(*) from generate_series(0,2) tier where (select count(distinct x->>'stimulusFamilyId') from jsonb_array_elements(p_run->'pool') x where x->>'trackId'=v_track and (x->>'difficultyTier')::integer=tier)<v_max)>0
      then raise exception 'Insufficient fresh progress stock'; end if;
    v_tiers:=v_tiers||jsonb_build_object(v_track,v_initial);
  end loop;
  for v_row in select value from jsonb_array_elements(p_run->'responses') loop
    select value into v_expected from jsonb_array_elements(p_run->'pool') where value->>'id'=v_row->>'questionId';
    v_status:=v_row->>'responseStatus'; v_track:=v_expected->>'trackId';
    if v_expected is null or not public.lp_progress_item_valid(v_row->'itemSnapshot',v_expected)
      or v_row->>'trackId' is distinct from v_track
      or v_row->>'stimulusFamilyId' is distinct from v_expected->>'stimulusFamilyId'
      or v_row->>'difficultyTier' is distinct from v_expected->>'difficultyTier'
      or v_row->>'responseId' is distinct from (p_run->>'attemptId')||':'||v_ordinal
      or coalesce(v_status,'') not in ('correct','incorrect','supported','skipped','no_response','media_failed')
      or (v_row->>'selected' is not null and not exists(select 1 from jsonb_array_elements(v_expected->'choices') x where x->>'id'=v_row->>'selected'))
    then raise exception 'Invalid progress response snapshot'; end if;
    v_before:=(v_tiers->>v_track)::integer; v_after:=v_before;
    if (v_expected->>'difficultyTier')::integer<>v_before then raise exception 'Invalid adaptive route'; end if;
    if v_status in ('correct','incorrect') then
      v_correct:=v_row->>'selected'=v_expected->>'answer';
      if v_row->>'selected' is null or v_row->>'mediaReady' is distinct from 'true'
        or v_row->>'supported' is distinct from 'false' or v_row->>'isCorrect' is distinct from v_correct::text
        or v_status is distinct from (case when v_correct then 'correct' else 'incorrect' end)
        then raise exception 'Invalid progress scoring'; end if;
      for v_role,v_cue in select key,value from jsonb_each(coalesce(v_expected->'audio','{}'::jsonb)) loop
        if jsonb_typeof(v_cue)='array' then
          v_index:=0;
          for v_audio in select value from jsonb_array_elements(v_row#>array['itemSnapshot','audio',v_role]) loop
            if v_audio->>'required'='true' and v_row#>>array['audioDelivery',v_role||':'||v_index] is distinct from 'completed'
              then raise exception 'Required progress audio not delivered'; end if;
            v_index:=v_index+1;
          end loop;
        elsif v_cue->>'required'='true' and v_row#>>array['audioDelivery',v_role] is distinct from 'completed'
          then raise exception 'Required progress audio not delivered'; end if;
      end loop;
      v_after:=greatest(0,least(2,v_before+case when v_correct then 1 else -1 end)); v_scored:=v_scored+1;
    elsif v_row->'isCorrect' is distinct from 'null'::jsonb then raise exception 'Unscored progress response has a score'; end if;
    -- End-early unanswered rows retain their snapshot but have no routing event.
    if (v_status in ('correct','incorrect') and not (v_row ?& array['routeBefore','routeAfter'])) or (v_row ? 'routeBefore' and (v_row->>'routeBefore' is distinct from v_before::text or v_row->>'routeAfter' is distinct from v_after::text))
      then raise exception 'Invalid adaptive route'; end if;
    v_tiers:=v_tiers||jsonb_build_object(v_track,v_after); v_ordinal:=v_ordinal+1;
  end loop;
  if (select count(distinct x->>'questionId') from jsonb_array_elements(p_run->'responses') x)<>v_ordinal
    or (select count(distinct x->>'stimulusFamilyId') from jsonb_array_elements(p_run->'responses') x)<>v_ordinal
    or v_scored>(p_run#>>'{plan,maximumValid}')::integer then raise exception 'Duplicate or excess progress response'; end if;
  for v_track in select jsonb_array_elements_text(v_track_ids) loop
    if p_run#>>array['tracks',v_track,'nextTier'] is distinct from v_tiers->>v_track
      then raise exception 'Progress track state does not match its answers'; end if;
    if p_run->>'status'='completed' and (select count(*) from jsonb_array_elements(p_run->'responses') x
      where x->>'trackId'=v_track and x->>'responseStatus' in ('correct','incorrect'))<v_min
      then raise exception 'Completed progress plan lacks independent evidence'; end if;
  end loop;
  if p_run->'currentItem' is distinct from 'null'::jsonb then
    select value into v_expected from jsonb_array_elements(p_run->'pool') where value->>'id'=p_run#>>'{currentItem,id}';
    if v_expected is null or not public.lp_progress_item_valid(p_run->'currentItem',v_expected)
      or exists(select 1 from jsonb_array_elements(p_run->'responses') x where x->>'questionId'=v_expected->>'id')
      or (v_expected->>'difficultyTier')::integer<>(v_tiers->>(v_expected->>'trackId'))::integer
      then raise exception 'Invalid pending progress item'; end if;
  end if;
  if p_previous is not null then
    if p_previous->>'status' in ('completed','partial') and p_previous<>p_run
      then raise exception 'Terminal progress evidence is immutable'; end if;
    foreach v_key in array array['attemptId','studentId','classId','teacherId','assignmentId','contentVersion',
      'difficultyVersion','policyVersion','policySnapshot','startingPoints','exposureSnapshot','plan','seed','pool','startedAt'] loop
      if p_previous->v_key is distinct from p_run->v_key then raise exception 'Frozen progress metadata changed'; end if;
    end loop;
    foreach v_key in array array['responses','routeDecisions','warmupRecords','pauseEvents'] loop
      if jsonb_array_length(p_run->v_key)<jsonb_array_length(p_previous->v_key)
        or exists(select 1 from jsonb_array_elements(p_previous->v_key) with ordinality old(value,n)
          where old.value is distinct from (p_run->v_key)->(old.n::integer-1))
        then raise exception 'Committed progress history changed'; end if;
    end loop;
  end if;
end;
$$;

-- Progress routes may legitimately get easier. Their append-only history is
-- validated below, so cumulative max/OR merging would corrupt the checkpoint.
CREATE OR REPLACE FUNCTION public.lp_forward_merge_progress(p_area text, p_existing jsonb, p_incoming jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_area = 'daily_mission' then public.lp_merge_daily_mission(p_existing, p_incoming)
    when p_area in ('profile','progress_check') then p_incoming
    when p_area = 'phonics_quest' then public.lp_merge_phonics_quest(p_existing, p_incoming)
    when p_area = 'hollow' then public.lp_merge_hollow(p_existing, p_incoming)
    when p_area = 'transfer_missions' then public.lp_merge_transfer_missions(p_existing, p_incoming)
    when p_area = 'el_quest' then public.lp_merge_el_quest(p_existing, p_incoming)
    else public.lp_jsonb_forward_merge(p_existing, p_incoming)
  end;
$function$;

create function public.validate_progress_checkpoint() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op='UPDATE' and old.area='progress_check' and (new.area<>old.area or new.key<>old.key or new.student_id<>old.student_id)
    then raise exception 'Progress checkpoint ownership is immutable'; end if;
  if new.area='progress_check' then
    if not exists(select 1 from public.students where id=new.student_id and teacher_id::text=new.payload->>'teacherId' and class_id::text=new.payload->>'classId' and archived_at is null)
      then raise exception 'Invalid progress checkpoint owner'; end if;
    if new.key is distinct from 'run:'||(new.payload->>'attemptId') or new.student_id::text is distinct from new.payload->>'studentId'
      then raise exception 'Invalid progress checkpoint owner'; end if;
    perform public.lp_validate_progress_run(new.payload,case when tg_op='UPDATE' then old.payload else null end);
    if tg_op='INSERT' then perform public.lp_validate_progress_exposure(new.student_id,new.payload); end if;
  end if;
  return new;
end;
$$;
create trigger student_progress_adaptive_checkpoint before insert or update on public.student_progress
  for each row execute function public.validate_progress_checkpoint();

create function public.lp_progress_history(p_student_id uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  with records as (
    select aa.payload, aa.completed_at as at from public.assessment_attempts aa where aa.student_id=p_student_id::text
    union all select jsonb_build_object('assessmentType','supported_practice','studentId',p_student_id,
      'questionRecords',coalesce((select jsonb_agg(x) from jsonb_path_query(sp.payload,'$.**.steps[*]') x),'[]'::jsonb)),sp.updated_at
      from public.student_progress sp where sp.student_id=p_student_id and sp.area<>'progress_check'
    union all select jsonb_build_object('assessmentType','progress_draft','studentId',p_student_id,'attemptId',sp.payload->'attemptId',
      'questionRecords',sp.payload->'responses'),sp.updated_at from public.student_progress sp
      where sp.student_id=p_student_id and sp.area='progress_check'
  ) select coalesce(jsonb_agg(jsonb_build_object('attemptId',payload->'attemptId','studentId',p_student_id,
    'assessmentType',payload->'assessmentType','contentVersion',payload->'contentVersion','policyVersion',payload->'policyVersion',
    'administrationStatus',payload->'administrationStatus','completedAt',payload->'completedAt',
    'metadata',jsonb_build_object('difficultyVersion',payload#>'{metadata,difficultyVersion}'),
    'questionRecords',coalesce((select jsonb_agg(jsonb_build_object('questionId',q->'questionId',
      'stimulusFamilyId',q->'stimulusFamilyId','trackId',q->'trackId','difficultyTier',q->'difficultyTier',
      'responseStatus',q->'responseStatus','routeAfter',q->'routeAfter',
      'sourceStimulusFamilyId',q->'sourceStimulusFamilyId','exposure',q->'exposure',
      'sourcePaths',coalesce((select jsonb_agg(distinct path) from jsonb_path_query(q,'$.** ? (@.type() == "string")') path
        where path#>>'{}' ~ '^/audio/.*/assessment_passage/' or path#>>'{}'=q->>'passageAudioPath' or path#>>'{}'=q#>>'{features,passageAudioPath}'),'[]'::jsonb)))
      from jsonb_array_elements(coalesce(payload->'questionRecords','[]'::jsonb)) q),'[]'::jsonb)) order by at),'[]'::jsonb) from records;
$$;

create function public.lp_validate_progress_exposure(p_student_id uuid,p_run jsonb) returns void
language plpgsql stable security definer set search_path = '' as $$
declare v_history jsonb; v_question jsonb; v_item jsonb; v_source jsonb;
begin
  for v_history in select value from jsonb_array_elements(public.lp_progress_history(p_student_id)) loop
    if v_history->>'attemptId' is not distinct from p_run->>'attemptId' then continue; end if;
    for v_question in select value from jsonb_array_elements(v_history->'questionRecords') loop
      for v_item in select value from jsonb_array_elements(p_run->'pool') loop
        if v_item->>'id'=v_question->>'questionId' or v_item->>'stimulusFamilyId'=v_question->>'stimulusFamilyId'
          or coalesce(v_item->'enemyItemGroups','[]'::jsonb) ? coalesce(v_question->>'questionId','')
          or coalesce(v_item->'enemyItemGroups','[]'::jsonb) ? coalesce(v_question->>'stimulusFamilyId','')
          or coalesce(v_item->'enemyItemGroups','[]'::jsonb) ? coalesce(v_question->>'sourceStimulusFamilyId','')
          then raise exception 'Previously exposed progress family is in the frozen pool'; end if;
        for v_source in select value from jsonb_array_elements(v_item#>'{media,requiredSources}') where value->>'role'='passage' loop
          if coalesce(v_question->'sourcePaths','[]'::jsonb) ? (v_source->>'path')
            then raise exception 'Previously exposed passage is in the frozen pool'; end if;
        end loop;
      end loop;
    end loop;
  end loop;
end;
$$;
revoke all on function public.lp_validate_progress_exposure(uuid,jsonb) from public,anon,authenticated;

create function public.lp_progress_load(p_student_id uuid,p_assignment_id uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('ok',true,'run',(select payload from public.student_progress
    where student_id=p_student_id and area='progress_check' and coalesce(payload->>'assignmentId','')=coalesce(p_assignment_id::text,'')
    order by updated_at desc limit 1),'history',public.lp_progress_history(p_student_id));
$$;

create function public.teacher_get_progress_run(p_student_id uuid,p_assignment_id uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_current_actor_teacher_access();
  if not exists(select 1 from public.students where id=p_student_id and teacher_id=auth.uid() and archived_at is null)
    then return jsonb_build_object('ok',false,'error','student_not_owned'); end if;
  if p_assignment_id is not null and not exists(select 1 from public.student_focus_sessions s join public.student_focus_session_members m on m.session_id=s.id
    where s.id=p_assignment_id and s.teacher_id=auth.uid() and s.target='progress_check' and m.student_id=p_student_id)
    then return jsonb_build_object('ok',false,'error','assignment_mismatch'); end if;
  return public.lp_progress_load(p_student_id,p_assignment_id);
end;
$$;

create function public.student_get_progress_run(p_token text,p_session_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_student public.students;
begin
  v_student:=public.student_from_token(p_token);
  if v_student.id is null then return jsonb_build_object('ok',false,'error','invalid_session'); end if;
  if not exists(select 1 from public.student_focus_sessions s join public.student_focus_session_members m on m.session_id=s.id
    where s.id=p_session_id and s.target='progress_check' and s.status='active' and s.expires_at>now() and m.active and m.student_id=v_student.id)
    then return jsonb_build_object('ok',false,'error','assignment_mismatch'); end if;
  return public.lp_progress_load(v_student.id,p_session_id);
end;
$$;

create function public.lp_progress_attempt_valid(p_attempt jsonb,p_run jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(p_attempt->>'assessmentVersion'='progress-check-v1'
    and p_attempt#>>'{metadata,reportingMode}'='descriptive'
    and p_attempt#>>'{metadata,difficultyVersion}'=p_run->>'difficultyVersion'
    and p_attempt#>'{metadata,planSnapshot}'=p_run->'plan'
    and p_attempt#>'{metadata,startingPoints}'=p_run->'startingPoints'
    and p_attempt#>'{metadata,exposureSnapshot}'=p_run->'exposureSnapshot'
    and p_attempt#>'{metadata,warmupRecords}'=p_run->'warmupRecords'
    and p_attempt#>'{metadata,routeDecisions}'=p_run->'routeDecisions'
    and p_attempt#>'{metadata,policySnapshot}'=(p_run->'policySnapshot')||'{"progressDoesNotAffectPlacement":true}'::jsonb
    and p_attempt#>>'{metadata,result,reportingMode}'='descriptive'
    and p_attempt#>>'{metadata,result,calibrated}'='false'
    and p_attempt#>'{metadata,result}'=p_attempt#>'{metrics,progressProfile}'
    and p_attempt->'masteredItems'='[]'::jsonb and p_attempt->'developingItems'='[]'::jsonb and p_attempt->'needsSupportItems'='[]'::jsonb
    and jsonb_array_length(p_attempt#>'{metadata,result,strands}')=jsonb_array_length(p_run#>'{plan,trackIds}')
    and not exists(select 1 from jsonb_array_elements(p_attempt#>'{metadata,result,strands}') strand
      where not (p_run#>'{plan,trackIds}') ? (strand->>'trackId')
        or strand->>'independentCount' is distinct from (select count(*)::text from jsonb_array_elements(p_run->'responses') x where x->>'trackId'=strand->>'trackId' and x->>'responseStatus' in ('correct','incorrect'))
        or strand->>'correctCount' is distinct from (select count(*)::text from jsonb_array_elements(p_run->'responses') x where x->>'trackId'=strand->>'trackId' and x->>'responseStatus'='correct')
        or strand->>'incorrectCount' is distinct from (select count(*)::text from jsonb_array_elements(p_run->'responses') x where x->>'trackId'=strand->>'trackId' and x->>'responseStatus'='incorrect'))
    and (select count(distinct x->>'trackId') from jsonb_array_elements(p_attempt#>'{metadata,result,strands}') x)=jsonb_array_length(p_run#>'{plan,trackIds}'),false);
$$;
revoke all on function public.lp_progress_attempt_valid(jsonb,jsonb) from public,anon,authenticated;

create function public.lp_progress_save(p_student_id uuid,p_teacher_id uuid,p_class_id uuid,p_assignment_id uuid,p_run jsonb,p_attempt jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_config jsonb; v_payload jsonb; v_existing jsonb; v_terminal boolean; v_total integer; v_correct integer; v_pool jsonb;
begin
  -- Send only frozen pool IDs across the wire; restore exact published items.
  if jsonb_typeof(p_run->'pool')='array' and jsonb_typeof(p_run#>'{pool,0}')='string' then
    select jsonb_agg(item order by requested.n) into v_pool from jsonb_array_elements(p_run->'pool') with ordinality requested(id,n)
      join public.progress_test_banks bank on bank.version=p_run->>'contentVersion'
      cross join lateral jsonb_array_elements(bank.manifest->'items') item where item->>'id'=requested.id#>>'{}';
    if jsonb_array_length(v_pool) is distinct from jsonb_array_length(p_run->'pool')
      then return jsonb_build_object('ok',false,'error','invalid_progress_pool'); end if;
    p_run:=p_run||jsonb_build_object('pool',v_pool);
  end if;
  if p_run->>'studentId' is distinct from p_student_id::text or p_run->>'teacherId' is distinct from p_teacher_id::text
    or p_run->>'classId' is distinct from p_class_id::text or coalesce(p_run->>'assignmentId','') is distinct from coalesce(p_assignment_id::text,'')
    then return jsonb_build_object('ok',false,'error','ownership_mismatch'); end if;
  perform 1 from public.students where id=p_student_id and teacher_id=p_teacher_id and class_id=p_class_id and archived_at is null for update;
  if not found then return jsonb_build_object('ok',false,'error','student_not_owned'); end if;
  if p_assignment_id is not null then
    select m.resolved_config into v_config from public.student_focus_sessions s join public.student_focus_session_members m on m.session_id=s.id
      where s.id=p_assignment_id and s.teacher_id=p_teacher_id and s.class_id=p_class_id and s.target='progress_check' and m.student_id=p_student_id;
    if v_config is null or not public.lp_progress_config_valid(v_config,p_run->>'contentVersion')
      or v_config->>'plan_kind' is distinct from p_run#>>'{plan,id}'
      or (v_config->>'plan_kind'='focused' and v_config->>'track_id' is distinct from p_run#>>'{plan,trackIds,0}')
      then return jsonb_build_object('ok',false,'error','assignment_mismatch'); end if;
  end if;
  v_terminal:=p_run->>'status' in ('completed','partial');
  if v_terminal is distinct from (p_attempt is not null) then return jsonb_build_object('ok',false,'error','terminal_attempt_required'); end if;
  perform public.lp_validate_progress_run(p_run);
  if v_terminal then
    select count(*),count(*) filter(where x->>'responseStatus'='correct') into v_total,v_correct
      from jsonb_array_elements(p_run->'responses') x where x->>'responseStatus' in ('correct','incorrect');
    if not public.lp_progress_attempt_valid(p_attempt,p_run) or octet_length(p_attempt::text)>4900000 or p_attempt->>'attemptId' is distinct from p_run->>'attemptId'
      or p_attempt->>'assessmentType' is distinct from 'adaptive_progress_test' or p_attempt#>>'{metadata,instrumentId}' is distinct from 'literacypath_progress'
      or p_attempt->>'contentVersion' is distinct from p_run->>'contentVersion' or p_attempt->>'policyVersion' is distinct from p_run->>'policyVersion'
      or p_attempt->>'administrationStatus' is distinct from p_run->>'status' or p_attempt->'questionRecords' is distinct from p_run->'responses'
      or p_attempt->>'passed' is distinct from 'false' or p_attempt->'accuracy' is distinct from 'null'::jsonb
      or p_attempt->>'skillLevel' is distinct from '0' or p_attempt->>'skillPhase' is distinct from '0'
      or p_attempt->>'totalQuestions' is distinct from v_total::text or p_attempt->>'correctCount' is distinct from v_correct::text
      or p_attempt->>'startedAt' is distinct from p_run->>'startedAt' or p_attempt->>'completedAt' is distinct from p_run->>'completedAt'
      then return jsonb_build_object('ok',false,'error','invalid_progress_attempt'); end if;
    v_payload:=p_attempt||jsonb_build_object('studentId',p_student_id::text,'teacherId',p_teacher_id::text,'classId',p_class_id::text,
      'studentName',(select name from public.students where id=p_student_id));
    select payload into v_existing from public.assessment_attempts where attempt_id=p_run->>'attemptId';
    if v_existing is not null and v_existing<>v_payload then return jsonb_build_object('ok',false,'error','attempt_conflict'); end if;
  end if;
  insert into public.student_progress(student_id,area,key,payload,updated_at)
    values(p_student_id,'progress_check','run:'||(p_run->>'attemptId'),p_run,now())
    on conflict(student_id,area,key) do update set payload=excluded.payload,updated_at=now();
  if v_terminal then
    insert into public.assessment_attempts(attempt_id,student_id,class_id,teacher_id,assessment_type,skill_id,skill_name,skill_level,skill_phase,
      started_at,completed_at,total_questions,correct_count,accuracy,status,administration_status,schema_version,evidence_schema_version,
      assessment_version,content_version,policy_version,payload,raw_evidence)
    values(p_run->>'attemptId',p_student_id::text,p_class_id::text,p_teacher_id,'adaptive_progress_test','progress_check','Progress check',0,0,
      (p_run->>'startedAt')::timestamptz,(p_run->>'completedAt')::timestamptz,v_total,v_correct,null,p_run->>'status',p_run->>'status',4,1,
      p_attempt->>'assessmentVersion',p_run->>'contentVersion',p_run->>'policyVersion',v_payload,'{}'::jsonb)
    on conflict(attempt_id) do nothing;
    if p_assignment_id is not null then update public.student_focus_session_members set status='completed',completed_at=now(),updated_at=now()
      where session_id=p_assignment_id and student_id=p_student_id; end if;
  end if;
  return jsonb_build_object('ok',true,'attemptId',p_run->>'attemptId','terminal',v_terminal);
exception when invalid_text_representation or numeric_value_out_of_range or check_violation then
  return jsonb_build_object('ok',false,'error','invalid_progress_run');
end;
$$;

create function public.teacher_save_progress_run(p_run jsonb,p_attempt jsonb default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform public.assert_current_actor_teacher_access();
  return public.lp_progress_save((p_run->>'studentId')::uuid,auth.uid(),(p_run->>'classId')::uuid,nullif(p_run->>'assignmentId','')::uuid,p_run,p_attempt);
exception when invalid_text_representation then return jsonb_build_object('ok',false,'error','invalid_progress_run');
end;
$$;

create function public.student_save_progress_run(p_token text,p_session_id uuid,p_run jsonb,p_attempt jsonb default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_student public.students; v_teacher uuid; v_class uuid;
begin
  v_student:=public.student_from_token(p_token);
  if v_student.id is null then return jsonb_build_object('ok',false,'error','invalid_session'); end if;
  select s.teacher_id,s.class_id into v_teacher,v_class from public.student_focus_sessions s join public.student_focus_session_members m on m.session_id=s.id
    where s.id=p_session_id and s.target='progress_check' and s.status='active' and s.expires_at>now() and m.active and m.student_id=v_student.id;
  if v_teacher is null then return jsonb_build_object('ok',false,'error','assignment_mismatch'); end if;
  return public.lp_progress_save(v_student.id,v_teacher,v_class,p_session_id,p_run,p_attempt);
end;
$$;

create function public.validate_progress_attempt_archive() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_run jsonb;
begin
  if tg_op='UPDATE' and old.assessment_type='adaptive_progress_test' and to_jsonb(new)-array['created_at','updated_at']<>to_jsonb(old)-array['created_at','updated_at']
    then raise exception 'Progress assessment evidence is immutable'; end if;
  if new.assessment_type='adaptive_progress_test' then
    select payload into v_run from public.student_progress where student_id::text=new.student_id and area='progress_check' and key='run:'||new.attempt_id;
    if v_run is null or not public.lp_progress_attempt_valid(new.payload,v_run) or new.teacher_id::text is distinct from v_run->>'teacherId' or new.class_id is distinct from v_run->>'classId'
      or new.payload->'questionRecords' is distinct from v_run->'responses' or coalesce(v_run->>'status','') not in ('completed','partial')
      or new.payload->>'passed' is distinct from 'false' or new.accuracy is not null or new.skill_level<>0 or new.skill_phase<>0
      or new.assessment_version is distinct from 'progress-check-v1'
      or new.payload->>'assessmentType' is distinct from 'adaptive_progress_test'
      or new.payload->>'attemptId' is distinct from new.attempt_id
      or new.payload->>'studentId' is distinct from new.student_id
      or new.payload->>'teacherId' is distinct from new.teacher_id::text
      or new.payload->>'classId' is distinct from new.class_id
      or new.administration_status is distinct from v_run->>'status'
      or new.content_version is distinct from v_run->>'contentVersion'
      or new.policy_version is distinct from v_run->>'policyVersion'
      or new.total_questions<>(select count(*) from jsonb_array_elements(v_run->'responses') x where x->>'responseStatus' in ('correct','incorrect'))
      or new.correct_count<>(select count(*) from jsonb_array_elements(v_run->'responses') x where x->>'responseStatus'='correct')
      or new.payload#>>'{metadata,instrumentId}' is distinct from 'literacypath_progress'
      then raise exception 'Progress attempt lacks its validated frozen run'; end if;
    perform public.lp_validate_progress_run(v_run);
  end if;
  return new;
end;
$$;
create trigger assessment_attempts_progress_boundary before insert or update on public.assessment_attempts
  for each row execute function public.validate_progress_attempt_archive();

revoke all on function public.lp_progress_config_valid(jsonb,text),public.lp_progress_item_valid(jsonb,jsonb),
  public.lp_validate_progress_run(jsonb,jsonb),public.validate_progress_checkpoint(),public.lp_progress_history(uuid),
  public.lp_progress_load(uuid,uuid),public.lp_progress_save(uuid,uuid,uuid,uuid,jsonb,jsonb),public.validate_progress_attempt_archive(),
  public.teacher_get_progress_run(uuid,uuid),public.student_get_progress_run(text,uuid),
  public.teacher_save_progress_run(jsonb,jsonb),public.student_save_progress_run(text,uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.teacher_get_progress_run(uuid,uuid),public.teacher_save_progress_run(jsonb,jsonb) to authenticated;
grant execute on function public.student_get_progress_run(text,uuid),public.student_save_progress_run(text,uuid,jsonb,jsonb) to anon,authenticated;

create or replace function public.teacher_start_progress_check_session(
  p_class_id uuid,
  p_student_ids uuid[],
  p_assignments jsonb default '{}'::jsonb,
  p_duration_minutes integer default 60,
  p_content_version text default '',
  p_whole_class boolean default false
)
returns json
language plpgsql volatile security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_session public.student_focus_sessions;
  v_student_ids uuid[] := '{}'::uuid[];
  v_selection_scope text;
  v_student_id uuid;
  v_invalid_student uuid;
  v_busy_student uuid;
  v_config jsonb;
  v_shared_config jsonb := '{}'::jsonb;
  v_members json;
begin
  perform public.assert_current_actor_teacher_access();

  if p_class_id is null
    or p_assignments is null
    or jsonb_typeof(p_assignments) <> 'object'
    or octet_length(p_assignments::text) > 1000000
    or p_duration_minutes is null
    or p_duration_minutes not between 5 and 120
    or nullif(btrim(coalesce(p_content_version, '')), '') is null
    or char_length(btrim(p_content_version)) > 120
    or p_whole_class is null
  then
    return json_build_object('ok', false, 'error', 'invalid_payload');
  end if;

  perform 1 from public.classes class
  where class.id = p_class_id and class.teacher_id = v_actor
  for update;
  if not found then
    return json_build_object('ok', false, 'error', 'class_not_found');
  end if;

  if p_whole_class then
    if coalesce(cardinality(p_student_ids), 0) <> 0 then
      return json_build_object('ok', false, 'error', 'whole_class_ids_must_be_empty');
    end if;
    select coalesce(array_agg(student.id order by student.id), '{}'::uuid[])
      into v_student_ids
    from public.students student
    where student.class_id = p_class_id
      and student.teacher_id = v_actor
      and student.archived_at is null;
    if cardinality(v_student_ids) = 0 then
      return json_build_object('ok', false, 'error', 'class_has_no_active_students');
    end if;
    if cardinality(v_student_ids) > 200 then
      return json_build_object('ok', false, 'error', 'class_too_large');
    end if;
    v_selection_scope := 'whole_class';
  else
    if coalesce(cardinality(p_student_ids), 0) not between 1 and 200
      or (select count(distinct requested.id) from unnest(p_student_ids) requested(id)) <> cardinality(p_student_ids)
    then
      return json_build_object('ok', false, 'error', 'invalid_payload');
    end if;
    v_student_ids := p_student_ids;
    v_selection_scope := 'selected_students';
  end if;

  perform 1 from public.students student
  where student.id = any(v_student_ids)
  order by student.id
  for update;

  select requested.id into v_invalid_student
  from unnest(v_student_ids) requested(id)
  left join public.students student
    on student.id = requested.id
   and student.class_id = p_class_id
   and student.teacher_id = v_actor
   and student.archived_at is null
  where student.id is null
  order by requested.id
  limit 1;
  if v_invalid_student is not null then
    return json_build_object('ok', false, 'error', 'student_not_in_class', 'student_id', v_invalid_student);
  end if;

  -- Server-published bank and small per-learner plan only.
  if p_assignments ? '*' then
    if (select count(*) from jsonb_object_keys(p_assignments)) <> 1
      or not public.lp_progress_config_valid(p_assignments->'*',p_content_version)
    then return json_build_object('ok',false,'error','invalid_progress_assignment'); end if;
    v_shared_config := p_assignments->'*';
  else
    if (select count(*) from jsonb_object_keys(p_assignments)) <> cardinality(v_student_ids)
      then return json_build_object('ok',false,'error','missing_progress_assignment'); end if;
    for v_student_id in select unnest(v_student_ids) loop
      if not public.lp_progress_config_valid(p_assignments->v_student_id::text,p_content_version)
        then return json_build_object('ok',false,'error','invalid_progress_assignment','student_id',v_student_id); end if;
    end loop;
  end if;

  perform public.end_expired_student_focus_sessions();
  select requested.id into v_busy_student
  from unnest(v_student_ids) requested(id)
  join public.student_focus_session_members member on member.student_id = requested.id and member.active
  join public.student_focus_sessions session on session.id = member.session_id
    and session.status = 'active' and session.expires_at > now() and session.teacher_id <> v_actor
  order by requested.id limit 1;
  if v_busy_student is not null then
    return json_build_object('ok', false, 'error', 'student_busy', 'student_id', v_busy_student);
  end if;

  select requested.id into v_busy_student
  from unnest(v_student_ids) requested(id)
  join public.reading_sessions reading
    on requested.id = any(reading.student_ids)
   and reading.status = 'active'
   and reading.updated_at >= now() - interval '90 minutes'
  order by requested.id
  limit 1;
  if v_busy_student is not null then
    return json_build_object('ok', false, 'error', 'student_busy', 'student_id', v_busy_student);
  end if;

  update public.student_focus_session_members member
     set active = false, updated_at = now()
    from public.student_focus_sessions session
   where member.session_id = session.id and session.teacher_id = v_actor and session.status = 'active';
  update public.student_focus_sessions
     set status = 'ended', ended_at = coalesce(ended_at, now()), updated_at = now()
   where teacher_id = v_actor and status = 'active';

  insert into public.student_focus_sessions (
    teacher_id, class_id, target, content_version, selection_scope, expires_at
  ) values (
    v_actor, p_class_id, 'progress_check', btrim(p_content_version), v_selection_scope,
    now() + make_interval(mins => p_duration_minutes)
  ) returning * into v_session;

  insert into public.student_focus_session_members (session_id, student_id, resolved_config)
  select v_session.id, requested.id,
    case when p_assignments ? '*' then v_shared_config else p_assignments -> requested.id::text end
  from unnest(v_student_ids) requested(id);

  select coalesce(json_agg(json_build_object(
    'student_id', member.student_id, 'status', member.status, 'connected', false,
    'content_ok', member.content_ok, 'resolved_config', member.resolved_config
  ) order by student.name), '[]'::json)
  into v_members
  from public.student_focus_session_members member
  join public.students student on student.id = member.student_id
  where member.session_id = v_session.id;

  return json_build_object(
    'ok', true,
    'session', json_build_object(
      'id', v_session.id, 'teacher_id', v_session.teacher_id, 'class_id', v_session.class_id,
      'target', v_session.target, 'audience', v_session.selection_scope,
      'selection_scope', v_session.selection_scope, 'content_version', v_session.content_version,
      'status', v_session.status, 'started_at', v_session.started_at, 'expires_at', v_session.expires_at,
      'updated_at', v_session.updated_at, 'members', v_members
    )
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return json_build_object('ok', false, 'error', 'invalid_progress_assignment');
end;
$$;

revoke all on function public.teacher_start_progress_check_session(uuid, uuid[], jsonb, integer, text, boolean)
  from public, anon, authenticated;
grant execute on function public.teacher_start_progress_check_session(uuid, uuid[], jsonb, integer, text, boolean)
  to authenticated;


notify pgrst,'reload schema';
commit;
